 function formatBytes(value){const size=Math.max(0,Number(value)||0);if(size<1024)return `${size} B`;if(size<1048576)return `${(size/1024).toFixed(size<10240?1:0)} KB`;return `${(size/1048576).toFixed(1)} MB`;}
