 function composerAttachments(draft){if(!draft.attachments?.length&&!draft.attachmentBusy)return '';return `<div class="mail-composer-attachments" aria-label="Archivos preparados">${draft.attachments.map(file=>`<span>${file.inline?composerIcon('compose-image'):composerIcon('compose-attach')}<strong>${escape(file.name)}</strong><small>${escape(formatBytes(file.size))}</small><button type="button" onclick="ModernoMail.removeComposerAttachment('${escape(file.id)}')" aria-label="Quitar ${escape(file.name)}">×</button></span>`).join('')}${draft.attachmentBusy?'<span class="is-loading"><span class="lg-spin"></span><strong>Preparando archivo…</strong></span>':''}</div>`;}
 function composerProjectPicker(draft){return draft.projectPicker?'<span class="mail-project-picker-host"></span>':'';}
 function messageComposer(){const draft=state.composer;if(!draft)return '';const title=({new:'Mensaje nuevo',reply:'Responder',replyAll:'Responder a todos',forward:'Reenviar'})[draft.mode]||'Mensaje nuevo',floating=draft.mode==='new',expanded=floating&&draft.expanded,minimized=floating&&draft.minimized,expandIcon=expanded?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 4H4v5M15 20h5v-5M4 4l6 6M20 20l-6-6"></path></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 4h5v5M9 20H4v-5M20 4l-6 6M4 20l6-6"></path></svg>',backdrop=expanded?'<div class="mail-composer-backdrop" aria-hidden="true"></div>':'',bodyHtml=draft.bodyHtml||escape(draft.body||'').replace(/\n/g,'<br>');return `${backdrop}<form class="mail-composer${floating?' mail-composer--floating':''}${expanded?' is-expanded':''}${minimized?' is-minimized':''}" aria-label="${escape(title)}" onsubmit="ModernoMail.sendComposer(event)"><header class="mail-composer-header"><h1>${title}</h1><div class="mail-composer-window-actions">${floating?`<button type="button" onclick="ModernoMail.toggleComposerMinimize()" aria-label="${minimized?'Restaurar mensaje':'Minimizar mensaje'}" title="${minimized?'Restaurar':'Minimizar'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17h14"></path></svg></button><button type="button" onclick="ModernoMail.toggleComposerExpand()" aria-label="${expanded?'Restaurar tamaño':'Expandir mensaje'}" title="${expanded?'Restaurar tamaño':'Expandir'}">${expandIcon}</button>`:''}<button type="button" onclick="ModernoMail.closeComposer()" aria-label="Cerrar mensaje" title="Cerrar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"></path></svg></button></div></header><div class="mail-composer-body"><div class="mail-composer-fields"><div class="mail-composer-from"><span>De</span><strong>${escape(selectedConnection()?.email||'')}</strong></div><label class="mail-composer-recipient"><span>Para</span><input name="to" type="text" value="${escape(draft.to)}" placeholder="Destinatarios" autocomplete="off" oninput="ModernoMail.updateComposerField('to',this.value)" required><span class="mail-composer-copy-actions"><button type="button" onclick="ModernoMail.toggleComposerCopy('Cc')" aria-pressed="${draft.showCc}">Cc</button><button type="button" onclick="ModernoMail.toggleComposerCopy('Bcc')" aria-pressed="${draft.showBcc}">Cco</button></span></label>${draft.showCc?`<label><span>Cc</span><input name="cc" type="text" value="${escape(draft.cc)}" placeholder="Copia opcional" autocomplete="off" oninput="ModernoMail.updateComposerField('cc',this.value)"></label>`:'<input type="hidden" name="cc" value="">'}${draft.showBcc?`<label><span>Cco</span><input name="bcc" type="text" value="${escape(draft.bcc)}" placeholder="Copia oculta opcional" autocomplete="off" oninput="ModernoMail.updateComposerField('bcc',this.value)"></label>`:'<input type="hidden" name="bcc" value="">'}<label><span>Asunto</span><input name="subject" type="text" value="${escape(draft.subject)}" placeholder="Asunto" maxlength="500" oninput="ModernoMail.updateComposerField('subject',this.value)" required></label></div><div class="mail-composer-message"><div class="mail-composer-editor" contenteditable="true" role="textbox" aria-label="Mensaje" data-placeholder="Escribe tu mensaje" oninput="ModernoMail.updateComposerBody(this)">${bodyHtml}</div></div>${draft.quote?`<details class="mail-composer-quote"><summary>Ver mensaje original incluido</summary><pre>${escape(draft.quote.trim())}</pre></details>`:''}${composerAttachments(draft)}${state.error?`<p class="mail-setup-error" role="alert">${escape(state.error)}</p>`:''}</div><footer class="mail-composer-footer"><div class="mail-composer-footer-start"><button type="submit" class="mail-composer-send" ${state.busy||draft.attachmentBusy?'disabled':''}>${state.busy?'<span class="lg-spin"></span> Enviando…':`Enviar ${composerIcon('compose-send')}`}</button><div class="mail-composer-format" role="toolbar" aria-label="Formato de texto"><button type="button" onclick="ModernoMail.formatComposer('bold')" aria-label="Negrita" title="Negrita">${composerIcon('compose-bold')}</button><button type="button" onclick="ModernoMail.formatComposer('italic')" aria-label="Cursiva" title="Cursiva">${composerIcon('compose-italic')}</button><button type="button" onclick="ModernoMail.formatComposer('underline')" aria-label="Subrayado" title="Subrayado">${composerIcon('compose-underline')}</button></div><span class="mail-composer-tools-separator" aria-hidden="true"></span><div class="mail-composer-tools">${composerToolButton('attach','Adjuntar archivo','compose-attach')}${composerToolButton('image','Insertar imagen','compose-image')}${composerToolButton('template','Plantillas','compose-template')}${composerToolButton('emoji','Insertar emoji','compose-emoji')}</div></div><button type="button" class="mail-composer-discard" onclick="ModernoMail.closeComposer()" aria-label="Descartar borrador" title="Descartar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6m5 5v5m4-5v5"></path></svg></button>${composerToolPanel(draft)}</footer>${composerProjectPicker(draft)}</form>`;}
 function readerActions(){if(!state.openedMessage||(state.composer&&state.composer.mode!=='new'))return '';return `<button type="button" class="mail-reader-action" onclick="ModernoMail.compose('reply')"><img src="/brand/mail-icons/reply.svg?v=36715" alt="">Responder</button><button type="button" class="mail-reader-action" onclick="ModernoMail.compose('replyAll')"><img src="/brand/mail-icons/reply-all.svg?v=36715" alt="">Responder a todos</button><button type="button" class="mail-reader-action" onclick="ModernoMail.compose('forward')"><img src="/brand/mail-icons/forward.svg?v=36715" alt="">Reenviar</button><button type="button" class="mail-icon-button" onclick="ModernoMail.printMessage()" aria-label="Imprimir" title="Imprimir"><img src="/brand/mail-icons/print.svg?v=36715" alt=""></button>${state.activeFolder==='trash'?'':`<button type="button" class="mail-icon-button" onclick="ModernoMail.deleteOpenedMessage()" aria-label="Eliminar" title="Mover a la papelera"><img src="/brand/mail-icons/delete.svg?v=36715" alt=""></button>`}`;}
 const pageIcons={prev:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"></path></svg>',next:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg>',down:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"></path></svg>'};
 function pageSequence(pageNumber,pageCount){if(pageCount<=5)return Array.from({length:pageCount},(_,index)=>index+1);if(pageNumber<=3)return [1,2,3,4,'end'];if(pageNumber>=pageCount-2)return ['start',pageCount-3,pageCount-2,pageCount-1,pageCount];return ['start',pageNumber-1,pageNumber,pageNumber+1,'end'];}
 function pageLink(page,pageNumber){const active=page===pageNumber;return `<button type="button" class="mail-pagination-link${active?' is-active':''}" onclick="ModernoMail.goPage(${page-1})" ${state.loading?'disabled':''} ${active?'aria-current="page"':''} aria-label="Página ${page}">${page}</button>`;}
 function paginationControls(){if(!state.mailboxTotal&&!state.messages.length)return '';const total=Math.max(state.mailboxTotal,state.messages.length),pageCount=Math.max(1,Math.ceil(total/state.pageSize)),pageNumber=Math.min(pageCount,state.pageIndex+1),atStart=pageNumber===1||state.loading,atEnd=pageNumber===pageCount||state.loading,pages=pageSequence(pageNumber,pageCount).map(page=>typeof page==='number'?pageLink(page,pageNumber):'<span class="mail-pagination-ellipsis" aria-hidden="true">•••</span>').join('');return `<nav class="mail-pagination" aria-label="Paginación del correo"><ul class="mail-pagination-content"><li class="mail-pagination-item mail-pagination-summary"><span>Página <strong>${pageNumber}</strong> de <strong>${pageCount}</strong></span></li><li class="mail-pagination-item mail-pagination-pages"><button type="button" class="mail-pagination-link mail-pagination-previous" onclick="ModernoMail.goPage(${state.pageIndex-1})" ${atStart?'disabled':''} aria-label="Página anterior">${pageIcons.prev}<span>Anterior</span></button>${pages}<button type="button" class="mail-pagination-link mail-pagination-next" onclick="ModernoMail.goPage(${state.pageIndex+1})" ${atEnd?'disabled':''} aria-label="Página siguiente"><span>Siguiente</span>${pageIcons.next}</button></li><li class="mail-pagination-item mail-pagination-size"><span class="mail-native-select"><select aria-label="Correos por página" onchange="ModernoMail.changePageSize(this.value)" ${state.loading?'disabled':''}>${[10,20,50,100].map(size=>`<option value="${size}" ${state.pageSize===size?'selected':''}>${size} / página</option>`).join('')}</select>${pageIcons.down}</span></li></ul></nav>`;}
 function loadingButton(label='Cargando correos…'){return `<div class="mail-loading-state" role="status"><button type="button" class="mail-loading-button mail-loading-button--outline" disabled><svg class="mail-spinner" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M21 12a9 9 0 0 0-9-9"></path></svg><span>${label}</span></button></div>`;}
 function inboxView(){
  const folder=folders[state.activeFolder]||folders.inbox;
  const listBody=!state.mailboxLoaded?'<div class="mail-inbox-skeleton" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span></div>':state.messages.length?state.messages.map(messageRow).join(''):`<div class="mail-inbox-empty"><strong>No hay correos en ${escape(folder.label.toLowerCase())}</strong><span>Los mensajes de esta carpeta aparecerán aquí.</span></div>`,embeddedComposer=state.composer&&state.composer.mode!=='new',detail=!!state.openedMessage||!!embeddedComposer,toolbarStart=detail?`<button type="button" class="mail-reader-back" onclick="${embeddedComposer?'ModernoMail.closeComposer()':'ModernoMail.closeMessage()'}"><img src="/brand/mail-icons/back.svg?v=36706" width="18" height="18" alt="">Volver</button>`:searchBox(),deleteButton=!detail&&state.activeFolder!=='trash'&&state.selectedMessageIds.length?`<button type="button" class="mail-icon-button mail-delete-button" onclick="ModernoMail.trashSelected()" ${state.loading?'disabled':''} aria-label="Mover ${state.selectedMessageIds.length} correo${state.selectedMessageIds.length===1?'':'s'} a la papelera" title="Mover a la papelera"><img src="/brand/mail-icons/trash.svg?v=36711" width="18" height="18" alt=""></button>`:'';
  return `<section class="mail-workspace" aria-label="Bandeja de ${escape(folder.label.toLowerCase())}"><aside class="mail-folders"><button type="button" class="mail-compose-button" onclick="ModernoMail.compose('new')"><span><img src="/brand/mail-icons/compose.svg?v=36711" width="18" height="18" alt="">Redactar</span>${arrowIcon}</button><nav aria-label="Carpetas de correo">${Object.keys(folders).map(folderButton).join('')}</nav>${accountSwitcher()}</aside><main class="mail-inbox-panel"><header class="mail-inbox-toolbar">${toolbarStart}<div class="mail-toolbar-actions">${deleteButton}${readerActions()}${detail?'':`<button type="button" class="mail-icon-button" onclick="ModernoMail.refreshInbox()" ${state.loading?'disabled':''} aria-label="Actualizar ${escape(folder.label.toLowerCase())}" title="Actualizar"><img src="/brand/mail-icons/refresh.svg?v=36711" width="18" height="18" alt=""></button>`}<button type="button" class="mail-icon-button" onclick="ModernoMail.openSettings()" aria-label="Ajustes" title="Ajustes"><img src="/brand/mail-icons/settings.svg?v=36711" width="18" height="18" alt=""></button></div></header><div class="mail-inbox-content${detail?' mail-inbox-content--reader':' mail-inbox-content--list'}">${!state.composer&&state.error?`<p class="mail-setup-error" role="alert">${escape(state.error)}</p>`:''}${embeddedComposer?messageComposer():state.openedMessage?messageReader():`<div class="mail-list-scroll"><div class="mail-message-list">${listBody}</div></div>${paginationControls()}`}${state.loading?loadingButton():''}</div></main></section>`;
 }
 function renderMail(){
  ensure();if(state.provider&&state.surface==='mail')return renderSetup(state.provider);
  if(connectedAccounts().length)return inboxView();
  if(!state.loaded)return `<section class="mail-connect-page" aria-busy="true">${loadingButton('Cargando Mail…')}</section>`;
  return `<section class="mail-connect-page" aria-labelledby="mail-connect-title"><div class="mail-connect-empty"><header class="mail-connect-header"><div class="mail-connect-media" aria-hidden="true"><svg width="200" height="120" viewBox="0 0 200 120" fill="none" xmlns="http://www.w3.org/2000/svg"><g class="mail-node-lines" stroke-width="1.5" stroke-dasharray="4 3"><line x1="100" y1="60" x2="44" y2="30"></line><line x1="100" y1="60" x2="44" y2="90"></line><line x1="100" y1="60" x2="156" y2="30"></line><line x1="100" y1="60" x2="156" y2="90"></line></g><circle cx="100" cy="60" r="18" class="mail-node-center" stroke-width="1.5"></circle><circle cx="100" cy="60" r="6" class="mail-node-center-ring"></circle><circle cx="100" cy="60" r="2.5" class="mail-node-center-dot"></circle>${[[44,30],[44,90],[156,30],[156,90]].map(([x,y])=>`<g class="mail-node-remote"><circle cx="${x}" cy="${y}" r="14" stroke-width="1.5"></circle><rect x="${x-7}" y="${y-4}" width="14" height="3" rx="1.5"></rect><rect x="${x-4}" y="${y+2}" width="8" height="2" rx="1"></rect></g>`).join('')}<circle cx="72" cy="40" r="2" class="mail-node-float-primary"></circle><circle cx="128" cy="80" r="2" class="mail-node-float-primary"></circle><circle cx="72" cy="80" r="1.5" class="mail-node-float-muted"></circle><circle cx="128" cy="40" r="1.5" class="mail-node-float-muted"></circle></svg></div><h2 id="mail-connect-title">Conecta tu correo</h2><p>Aún no hay ninguna cuenta conectada. Elige un servicio para comprobarlo y empezar a usarlo en Moderno.app.</p></header>${chooser()}${state.error?`<p class="mail-setup-error" role="alert">${escape(state.error)}</p>`:'<p class="mail-connect-note">Puedes conectar más de una cuenta y desconectarla cuando quieras.</p>'}</div></section>`;
 }
 function integrationCards(){ensure();return ['gmail','icloud'].map(provider=>{const data=providers[provider],rows=state.connections.filter(row=>row.provider===provider),row=rows[0];return `<article class="connection-card connection-card--mail"><div class="connection-card-provider">${mark(provider)}<div><h3>${data.name}</h3><p>${provider==='gmail'?'Consulta, organiza y envía correo con Google.':'Consulta y envía correo mediante tu cuenta de iCloud.'}</p></div></div>${row?`<span class="chip">Conectado · ${escape(row.email)}</span><div class="connection-card-actions"><button class="btn btn-ghost" onclick="ModernoMail.recheck('${escape(row.id)}')">Comprobar</button><button class="btn btn-ghost" onclick="ModernoMail.disconnect('${escape(row.id)}')">Desconectar</button></div>`:`<button class="btn btn-ghost" onclick="ModernoMail.open('${provider}','integrations')">Conectar</button>`}</article>`;}).join('');}
 global.ModernoMail={configure,load,open,back,onNavigate,submit,recheck,disconnect,refreshInbox,switchFolder,selectAccount,changePageSize,goPage,toggleMessage,openMessage,closeMessage,trashSelected,filterMessages,chooseSearch,searchKey,compose,updateComposerField,updateComposerBody,formatComposer,toggleComposerCopy,toggleComposerMenu,chooseComposerFiles,removeComposerAttachment,openComposerProjectPicker,closeComposerProjectPicker,selectComposerProject,attachComposerProjectFile,saveComposerTemplate,applyComposerTemplate,insertComposerEmoji,toggleComposerExpand,toggleComposerMinimize,closeComposer,sendComposer,printMessage,deleteOpenedMessage,downloadAttachment,openSettings,renderMail,setupFor,integrationCards,handleOAuthResult};
